import json, os, subprocess

item = _items[0]["json"]
slug = item["slug"]
root = "/home/node/files/films/" + slug
script_path = os.path.join(root, "script.json")
if not os.path.exists(script_path):
    raise RuntimeError("project not found: " + root + " — run the Script stage first")
with open(script_path) as fh:
    script = json.load(fh)

fps = int(script.get("fps", 25))
chars = {c["id"]: c for c in script.get("characters", [])}

# Durations recorded by the Animate (Seedance) stage from the real clips.
proj_path = os.path.join(root, "project.json")
proj = {}
if os.path.exists(proj_path):
    try:
        with open(proj_path) as fh:
            proj = json.load(fh) or {}
    except (ValueError, OSError):
        proj = {}
videos_stage = ((proj.get("stages") or {}).get("videos") or {})
recorded = videos_stage.get("durations") if isinstance(videos_stage.get("durations"), dict) else {}
failed_ids = videos_stage.get("failed_ids") if isinstance(videos_stage.get("failed_ids"), list) else []


def probe_duration(path):
    pr = subprocess.run(["ffprobe", "-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", path],
                        capture_output=True, text=True)
    if pr.returncode != 0:
        return None
    try:
        return float(pr.stdout.strip())
    except (TypeError, ValueError):
        return None


plan_shots = []
missing = []
for scene in script.get("scenes", []):
    for shot in scene.get("shots", []):
        sid = shot["id"]
        clip = os.path.join(root, "videos", sid + ".mp4")
        # No still fallback on this path: an unanimated shot is a gap to fill,
        # not something to render as a Ken Burns still.
        if not os.path.exists(clip):
            missing.append(sid)
            continue

        # The clip owns the timeline — never the voiceover mp3.
        dur = recorded.get(sid)
        if not isinstance(dur, (int, float)) or dur <= 0:
            dur = probe_duration(clip)
        if not dur or dur <= 0:
            raise RuntimeError("could not determine duration of " + clip)

        if shot.get("narration"):
            sub = shot["narration"].strip()
        else:
            sub = "\n".join(
                (chars.get(d.get("character", ""), {}).get("name") or d.get("character") or "?") + ": " + d.get("text", "")
                for d in shot.get("dialogue") or []
            )
        plan_shots.append({"id": sid, "dur": round(float(dur), 3), "subtext": sub, "clip": clip})

if missing:
    annotated = [sid + (" (generation failed)" if sid in failed_ids else "") for sid in missing]
    raise RuntimeError(
        "missing Seedance clip(s): " + ", ".join(annotated)
        + " — run the Animate (Seedance) stage first (videos/<shot>.mp4), then re-run this assembly"
    )

return [{"json": {"ok": True, "slug": slug, "fps": fps, "burn_subs": bool(item.get("burn_subs")),
                  "font_size": item.get("font_size", 24), "music_file": item.get("music_file") or "",
                  "music_volume": item.get("music_volume", 0.15), "shots": plan_shots}}]

